<?php $title='Abonnements'; $subtitle='Formules et adhésions de votre salle.'; $section='subscriptions'; require __DIR__.'/management_header.php'; ?>
<?php if ($canWrite): ?><div class="management-grid"><details class="card form-card"><summary>+ Enregistrer un abonnement</summary><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="subscription"><label>Membre actif *<select name="member_id" required><option value="">Sélectionner</option><?php foreach ($members as $m): ?><option value="<?= (int)$m['id'] ?>"><?= e($m['first_name'].' '.$m['last_name'].' · '.($m['card_number'] ?: 'Sans carte')) ?></option><?php endforeach; ?></select></label><label>Formule *<select name="plan_id" required><option value="">Sélectionner</option><?php foreach ($plans as $p): if (!$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>"><?= e($p['name'].' · '.dt($p['price'])) ?></option><?php endforeach; ?></select></label><label>Date de début *<input type="date" name="start_date" value="<?= date('Y-m-d') ?>" required></label><p class="form-hint">La date de fin est calculée selon la durée. Aucun paiement n’est créé automatiquement.</p><div class="form-actions"><button class="primary">Enregistrer</button></div></form></details><details class="card form-card"><summary>+ Créer une formule</summary><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="plan"><label>Nom *<input name="name" maxlength="100" required></label><label>Durée en jours *<input type="number" name="duration_days" min="1" max="3650" required></label><label>Prix (DT) *<input type="number" name="price" min="0" max="9999999" step="0.001" required></label><div class="form-actions"><button class="primary">Créer la formule</button></div></form></details></div><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Abonnements</h3><p><?= $total ?> adhésion(s) enregistrée(s)</p></div></div><div class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>FORMULE</th><th>DÉBUT</th><th>FIN</th><th>STATUT</th><?php if ($canWrite): ?><th>ACTION</th><?php endif; ?></tr></thead><tbody><?php foreach ($subscriptions as $s): $display=$s['status']==='active' && $s['end_date']<date('Y-m-d') ? 'Expiré' : ['active'=>'Actif','frozen'=>'Gelé','cancelled'=>'Annulé'][$s['status']]; ?><tr><td><strong><?= e($s['first_name'].' '.$s['last_name']) ?></strong></td><td><?= e($s['plan']) ?></td><td><?= e(date('d/m/Y',strtotime($s['start_date']))) ?></td><td><?= e(date('d/m/Y',strtotime($s['end_date']))) ?></td><td><span class="status <?= $display !== 'Actif' ? 'expired' : '' ?>"><?= e($display) ?></span></td><?php if ($canWrite): ?><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><select name="status" aria-label="Statut de l’abonnement"><?php foreach (['active'=>'Actif','frozen'=>'Gelé','cancelled'=>'Annulé'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $s['status']===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><button>OK</button></form></td><?php endif; ?></tr><?php endforeach; ?><?php if (!$subscriptions): ?><tr><td colspan="6" class="empty">Aucun abonnement enregistré.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="index.php?page=subscriptions&amp;p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="index.php?page=subscriptions&amp;p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div></section><section class="card management-table"><div class="card-head"><div><h3>Formules disponibles</h3><p>Durées et tarifs configurés</p></div></div><div class="table-scroll"><table><thead><tr><th>FORMULE</th><th>DURÉE</th><th>PRIX</th><th>STATUT</th></tr></thead><tbody><?php foreach ($plans as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= (int)$p['duration_days'] ?> jours</td><td><?= e(dt($p['price'])) ?></td><td><?= $p['is_active'] ? 'Active' : 'Inactive' ?></td></tr><?php endforeach; ?><?php if (!$plans): ?><tr><td colspan="4" class="empty">Aucune formule pour le moment.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require __DIR__.'/management_footer.php'; ?>
